import torch, triton
import reference, candidate
torch.manual_seed(0)
x = torch.randn(8192,2048,device='cuda')
for name, fn in [('reference(torch)', reference.run), ('candidate(triton)', candidate.run)]:
    for _ in range(5): fn(x)
    torch.cuda.synchronize(); t=time if False else None
    import time; ts=time.perf_counter()
    for _ in range(50): fn(x)
    torch.cuda.synchronize(); print(name, round((time.perf_counter()-ts)/50*1e3,3),'ms')
" 2>&1 | Select-String -NotMatch 'remark:'

